import test from 'node:test';import assert from 'node:assert/strict';
import {renderPhysicalSky,skyProjection} from '../src/physical-sky-renderer.mjs';
import {projectPerspective} from '../src/projection.mjs';
import {physicalSkyState} from '../src/sky-state.mjs';
const obs={utcMs:Date.parse('2026-01-15T02:00Z'),latDeg:28.54,lonDeg:-81.38};
const view={type:'camera',width:90,height:100,azDeg:180,altDeg:55,fovYDeg:60};
const h={altDeg:55,azDeg:180},s={id:'HIP:91262',hip:91262,bv:-.001,vmag:.03,...h,...projectPerspective(h,view)};
const render=(extra={})=>renderPhysicalSky([s],{observer:obs,view,scintillation:{strength:0},...extra});
const sum=a=>a.reduce((x,y)=>x+y,0);
test('CP6 display changes do not alter physical catalogue flux',()=>{const a=render({nominalExposure:5}),b=render({nominalExposure:40});assert.equal(sum(a.stellarLinear),sum(b.stellarLinear));assert.notEqual(a.effectiveExposure,b.effectiveExposure);});
test('CP6 direct cloud attenuation occurs exactly once in complete composition',()=>{const a=render(),b=render({atmosphere:{cloudTransmission:.3}});assert.ok(Math.abs(sum(b.stellarLinear)/sum(a.stellarLinear)-.3)<1e-10);});
test('CP6 source plus background composition is linear, not screen blending',()=>{const a=render();for(let i=0;i<a.linear.length;i++)assert.ok(Math.abs(a.linear[i]-a.stellarLinear[i]-a.backgroundLinear[i])<1e-12);});
test('CP6 no arbitrary solar-altitude multiplier on physical source photons',()=>{const a=render(),dayObs={...obs,utcMs:obs.utcMs+12*3600000},b=render({observer:dayObs});assert.equal(sum(a.stellarLinear),sum(b.stellarLinear));assert.ok(b.meanBackgroundY>a.meanBackgroundY*10000);assert.equal(b.detectableSources,0);});
test('CP6 calendar display mask removes only stellar layer, not physical illumination',()=>{const a=render(),b=render({displayTransmissionAt:()=>0});assert.equal(sum(b.stellarLinear),0);assert.deepEqual(a.backgroundLinear,b.backgroundLinear);assert.deepEqual(a.physicalState,b.physicalState);});
test('CP6 rejects stale physical ephemeris rather than drawing wrong Moon glare',()=>{const p=physicalSkyState(obs);assert.throws(()=>render({physicalState:{...p,utcMs:obs.utcMs-1000,source:'host'}}));assert.throws(()=>render({physicalState:p}));assert.doesNotThrow(()=>render({physicalState:{...p,source:'host verified ephemeris'}}));});
test('CP6 opaque physical Moon blocks source independently of illuminated fraction',()=>{const p=physicalSkyState(obs),r=render({physicalState:{...p,source:'explicit test fixture',moon:{...p.moon,...h,phaseAngleDeg:180,illuminatedFraction:0}}});assert.equal(sum(r.stellarLinear),0);});
test('CP6 reduced motion suppresses scintillation without freezing ephemeris',()=>{const a=render({reducedMotion:true,scintillation:{strength:.3}}),b=render({reducedMotion:true,scintillation:{strength:0}}),c=render({observer:{...obs,utcMs:obs.utcMs+3600000},reducedMotion:true});assert.deepEqual(a.stellarLinear,b.stellarLinear);assert.notEqual(a.physicalState.sun.altDeg,c.physicalState.sun.altDeg);});
test('CP6 inverse maps and solid angle are consistent, horizon masked',()=>{const all=skyProjection({type:'allsky',width:200,height:200});assert.ok(all.solidAngle(100,100)>0);assert.ok(all.solidAngle(100,100)>all.solidAngle(100,5));assert.equal(all.above(0,0),false);const cam=skyProjection(view);assert.ok(cam.above(s.x,s.y));const back=cam.unproject(s.x,s.y);assert.ok(Math.abs(back.altDeg-h.altDeg)<1e-9);});
test('CP6 DPR changes raster density not source energy per CSS area',()=>{const a=render({dpr:1}),b=render({dpr:2});assert.ok(Math.abs(sum(b.stellarLinear)/sum(a.stellarLinear)-4)<1e-8);assert.ok(Math.abs(b.meanBackgroundY/a.meanBackgroundY-1)<.02);});
test('CP6 reported display contrast respects an opaque calendar/foreground mask',()=>assert.equal(render({displayTransmissionAt:()=>0}).detectableSources,0));
test('CP6 observer elevation supplies atmosphere and physical topocentre consistently',()=>{const o={...obs,heightM:2800},r=render({observer:o});assert.equal(r.atmosphere.elevationM,2800);assert.ok(r.atmosphere.pressureHpa<800);assert.deepEqual(r.physicalState,physicalSkyState(o));});
test('CP6 mismatched explicit observer and atmospheric elevation is rejected',()=>assert.throws(()=>render({observer:{...obs,heightM:2800},atmosphere:{elevationM:0}})));
